# NotchAny widget data source: 网易云音乐
import base64
import json
import os
import re
import sqlite3
import subprocess
import time
import urllib.request
from pathlib import Path

CACHE = Path.home() / "Library/Caches/notchany-netease-music"
CACHE.mkdir(parents=True, exist_ok=True)
LYRIC_DIR = CACHE / "lyrics"
LYRIC_DIR.mkdir(exist_ok=True)
HELPER = CACHE / "mrinfo.swift"
ART_PATH = CACHE / "art.jpg"
LOGO_PATH = CACHE / "logo.png"
STATE_PATH = CACHE / "state.json"
BUNDLE = "com.netease.163music"
APP_PATH_HINT = "NeteaseMusic.app"
NCM_ICNS = "/Applications/NeteaseMusic.app/Contents/Resources/163Music.icns"


def ensure_logo():
    if LOGO_PATH.exists() and LOGO_PATH.stat().st_size > 100:
        return
    if not Path(NCM_ICNS).exists():
        return
    try:
        subprocess.run(
            ["sips", "-s", "format", "png", "-Z", "128", NCM_ICNS, "--out", str(LOGO_PATH)],
            capture_output=True,
            timeout=8,
        )
    except Exception:
        pass


def logo_b64():
    ensure_logo()
    if not LOGO_PATH.exists():
        return None
    try:
        return base64.b64encode(LOGO_PATH.read_bytes()).decode("ascii")
    except Exception:
        return None

SWIFT_SRC = r'''import Foundation
import Darwin

let handle = dlopen("/System/Library/PrivateFrameworks/MediaRemote.framework/MediaRemote", RTLD_NOW)
if handle == nil {
    fputs("dlopen MediaRemote failed\n", stderr)
    exit(1)
}

func load<T>(_ name: String) -> T {
    guard let s = dlsym(handle, name) else {
        fputs("missing \(name)\n", stderr)
        exit(1)
    }
    return unsafeBitCast(s, to: T.self)
}

let args = CommandLine.arguments
let mode = args.count > 1 ? args[1] : "info"

if mode == "seek" {
    typealias SetElapsed = @convention(c) (Double) -> Void
    let fn: SetElapsed = load("MRMediaRemoteSetElapsedTime")
    let t = args.count > 2 ? (Double(args[2]) ?? 0) : 0
    fn(max(0, t))
    exit(0)
}

typealias GetInfo = @convention(c) (DispatchQueue, @escaping (NSDictionary?) -> Void) -> Void
typealias GetPlaying = @convention(c) (DispatchQueue, @escaping (Bool) -> Void) -> Void
typealias GetPID = @convention(c) (DispatchQueue, @escaping (Int32) -> Void) -> Void

let getInfo: GetInfo = load("MRMediaRemoteGetNowPlayingInfo")
let getPlaying: GetPlaying = load("MRMediaRemoteGetNowPlayingApplicationIsPlaying")
let getPID: GetPID = load("MRMediaRemoteGetNowPlayingApplicationPID")

let q = DispatchQueue.global()
let g = DispatchGroup()
var info: NSDictionary?
var playing = false
var pid: Int32 = 0

g.enter(); getPlaying(q) { playing = $0; g.leave() }
g.enter(); getPID(q) { pid = $0; g.leave() }
g.enter(); getInfo(q) { info = $0; g.leave() }

_ = g.wait(timeout: .now() + 2.5)

var path = ""
if pid > 0 {
    var buf = [CChar](repeating: 0, count: 4096)
    let n = proc_pidpath(pid, &buf, UInt32(buf.count))
    if n > 0 { path = String(cString: buf) }
}

func jsonStr(_ s: String?) -> Any { s ?? NSNull() }

var artOut: Any = NSNull()
if let art = info?["kMRMediaRemoteNowPlayingInfoArtworkData"] as? Data, args.count > 2 {
    let p = args[2]
    if (try? art.write(to: URL(fileURLWithPath: p))) != nil { artOut = p }
}

let ts: Any
if let d = info?["kMRMediaRemoteNowPlayingInfoTimestamp"] as? Date {
    ts = d.timeIntervalSince1970
} else { ts = NSNull() }

let obj: [String: Any] = [
    "playing": playing,
    "pid": Int(pid),
    "path": path,
    "title": jsonStr(info?["kMRMediaRemoteNowPlayingInfoTitle"] as? String),
    "artist": jsonStr(info?["kMRMediaRemoteNowPlayingInfoArtist"] as? String),
    "album": jsonStr(info?["kMRMediaRemoteNowPlayingInfoAlbum"] as? String),
    "duration": info?["kMRMediaRemoteNowPlayingInfoDuration"] as? Double ?? NSNull(),
    "elapsed": info?["kMRMediaRemoteNowPlayingInfoElapsedTime"] as? Double ?? NSNull(),
    "rate": info?["kMRMediaRemoteNowPlayingInfoPlaybackRate"] as? Double ?? NSNull(),
    "timestamp": ts,
    "artwork": artOut,
]
let data = try! JSONSerialization.data(withJSONObject: obj, options: [])
FileHandle.standardOutput.write(data)
'''

EVENT = os.environ.get("NOTCH_WIDGET_EVENT") or "refresh"
try:
    PAYLOAD = json.loads(os.environ.get("NOTCH_WIDGET_PAYLOAD") or "{}")
except Exception:
    PAYLOAD = {}

ONLINE_LYRICS = os.environ.get("NOTCH_PARAM_ONLINE_LYRICS", "1") != "0"

MENU = {
    "bar": ("控制", "Control", "Playback"),
    "play": ("播放", "Play"),
    "pause": ("暂停", "Pause"),
    "next": ("下一个", "Next", "下一首"),
    "prev": ("上一个", "Previous", "上一首"),
    "vol_up": ("升高音量", "Increase Volume"),
    "vol_down": ("降低音量", "Decrease Volume"),
}


def load_state():
    try:
        return json.loads(STATE_PATH.read_text())
    except Exception:
        return {}


def save_state(st):
    try:
        STATE_PATH.write_text(json.dumps(st, ensure_ascii=False))
    except Exception:
        pass


def ncm_running():
    r = subprocess.run(["pgrep", "-x", "NeteaseMusic"], capture_output=True)
    return r.returncode == 0


def osa(script, timeout=8):
    r = subprocess.run(
        ["osascript", "-e", script],
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    return r.returncode, (r.stdout or "").strip(), (r.stderr or "").strip()


def classify_osa_err(err):
    e = err.lower()
    if "-1743" in err or "not authorized to send apple events" in e:
        return "permission_required"
    if "-25211" in err or "not allowed assistive" in e or "accessibility" in e:
        return "permission_required"
    if "1002" in err and "mentions" in e:
        return "permission_required"
    return None


def ensure_helper():
    if not HELPER.exists() or HELPER.read_text() != SWIFT_SRC:
        HELPER.write_text(SWIFT_SRC)


def run_helper(*args):
    ensure_helper()
    swift = "/usr/bin/swift"
    if not os.access(swift, os.X_OK):
        swift = "swift"
    cmd = [swift, str(HELPER), *args]
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=8)
    except Exception:
        return {}
    if r.returncode != 0:
        return {}
    raw = (r.stdout or b"").decode("utf-8", "replace").strip()
    if not raw:
        return {}
    try:
        return json.loads(raw)
    except Exception:
        return {}


def mr_info():
    return run_helper("info", str(ART_PATH))


def mr_seek(seconds):
    run_helper("seek", str(float(seconds)))


def is_ncm_now_playing(mr):
    path = mr.get("path") or ""
    return APP_PATH_HINT in path or path.endswith("NeteaseMusic")


def control_menu_script(body):
    # Must test `name of itm` (not bare `name`, which is the process name).
    bars = " or ".join(['n is "%s"' % x for x in MENU["bar"]])
    return f'''
tell application "System Events"
  tell process "NeteaseMusic"
    set barItem to missing value
    repeat with itm in menu bar items of menu bar 1
      set n to name of itm
      if {bars} then
        set barItem to itm
        exit repeat
      end if
    end repeat
    if barItem is missing value then error "no-control-menu"
    tell menu 1 of barItem
      {body}
    end tell
  end tell
end tell
'''


def menu_names():
    script = control_menu_script('''
      set out to {}
      repeat with mi in menu items
        try
          set end of out to name of mi as text
        end try
      end repeat
      return out
    ''')
    code, out, err = osa(script)
    if code != 0:
        return None, classify_osa_err(err) or "error", err
    names = [p.strip() for p in out.split(",") if p.strip()]
    return names, None, ""


def click_index(index, repeats=1):
    repeats = max(1, min(20, int(repeats)))
    script = control_menu_script(f'''
      repeat {repeats} times
        click menu item {index}
      end repeat
    ''')
    code, _, err = osa(script, timeout=8 + repeats)
    if code != 0:
        return classify_osa_err(err) or "error", err
    return "ok", ""


def click_named(candidates):
    names, perm, err = menu_names()
    if perm:
        return perm, err
    if not names:
        return "error", err or "empty-menu"
    want = set(candidates)
    hit = next((n for n in names if n in want), None)
    if not hit:
        return "error", "item-not-found:" + ",".join(names[:8])
    idx = names.index(hit) + 1
    return click_index(idx)


def click_playpause():
    return click_index(1)


def playing_from_menu():
    names, perm, err = menu_names()
    if perm:
        return None, perm, err
    if not names:
        return None, None, err
    first = names[0]
    if first in MENU["pause"]:
        return True, None, ""
    if first in MENU["play"]:
        return False, None, ""
    return None, None, first


def click_volume(delta_steps):
    if delta_steps == 0:
        return "ok", ""
    names = MENU["vol_up"] if delta_steps > 0 else MENU["vol_down"]
    n = min(20, abs(int(delta_steps)))
    hit = None
    listed, perm, err = menu_names()
    if perm:
        return perm, err
    if listed:
        hit = next((x for x in listed if x in names), None)
    if not hit:
        hit = names[0]
    script = control_menu_script(f'''
      repeat {n} times
        click menu item "{hit}"
      end repeat
    ''')
    code, _, err2 = osa(script, timeout=8 + n)
    if code != 0:
        return classify_osa_err(err2) or "error", err2
    return "ok", ""


def lookup_track(title, artist):
    title = (title or "").strip()
    artist = (artist or "").strip()
    if not title:
        return None
    db = Path.home() / "Library/Application Support/com.netease.163music/Documents/storage/sqlite_storage.sqlite3"
    if db.exists():
        try:
            con = sqlite3.connect(f"file:{db}?mode=ro", uri=True, timeout=1)
            cur = con.cursor()
            row = cur.execute(
                "SELECT id, jsonStr FROM historyTracks ORDER BY playtime DESC LIMIT 8"
            ).fetchall()
            for tid, js in row:
                try:
                    t = json.loads(js or "{}")
                except Exception:
                    continue
                name = (t.get("name") or "").strip()
                arts = t.get("artists") or []
                an = ",".join(a.get("name", "") for a in arts if isinstance(a, dict))
                if name == title and (not artist or artist in an or an in artist):
                    album = ((t.get("album") or {}) or {}).get("name") or ""
                    dur = t.get("duration")
                    return {
                        "id": str(t.get("id") or tid),
                        "title": name,
                        "artist": an,
                        "album": album,
                        "duration_ms": dur,
                    }
            con.close()
        except Exception:
            pass
    pl = Path.home() / "Library/Application Support/com.netease.163music/Documents/storage/file_storage/webdata/file/playingList"
    if pl.exists():
        try:
            data = json.loads(pl.read_text())
            for item in data.get("list") or []:
                tr = item.get("track") or {}
                name = (tr.get("name") or "").strip()
                arts = tr.get("artists") or []
                an = ",".join(a.get("name", "") for a in arts if isinstance(a, dict))
                if name == title and (not artist or artist in an or an in artist):
                    album = ((tr.get("album") or {}) or {}).get("name") or ""
                    return {
                        "id": str(tr.get("id") or item.get("id") or ""),
                        "title": name,
                        "artist": an,
                        "album": album,
                        "duration_ms": tr.get("duration"),
                    }
        except Exception:
            pass
    return None


def fallback_track():
    db = Path.home() / "Library/Application Support/com.netease.163music/Documents/storage/sqlite_storage.sqlite3"
    if not db.exists():
        return None
    try:
        con = sqlite3.connect(f"file:{db}?mode=ro", uri=True, timeout=1)
        row = con.execute(
            "SELECT id, jsonStr FROM historyTracks ORDER BY playtime DESC LIMIT 1"
        ).fetchone()
        con.close()
        if not row:
            return None
        t = json.loads(row[1] or "{}")
        arts = t.get("artists") or []
        an = ",".join(a.get("name", "") for a in arts if isinstance(a, dict))
        album = ((t.get("album") or {}) or {}).get("name") or ""
        return {
            "id": str(t.get("id") or row[0]),
            "title": (t.get("name") or "").strip(),
            "artist": an,
            "album": album,
            "duration_ms": t.get("duration"),
        }
    except Exception:
        return None


LRC_TS = re.compile(r"\[(\d+):(\d+(?:\.\d+)?)\]")


def parse_lrc(text):
    lines = []
    for raw in (text or "").splitlines():
        stamps = list(LRC_TS.finditer(raw))
        if not stamps:
            continue
        lyric = LRC_TS.sub("", raw).strip()
        if not lyric:
            continue
        lyric = lyric[:120]
        for m in stamps:
            t = int(m.group(1)) * 60 + float(m.group(2))
            lines.append({"t": round(t, 3), "text": lyric})
    lines.sort(key=lambda x: x["t"])
    return lines[:300]


def fetch_lyrics(track_id):
    if not track_id:
        return {"synced": False, "lines": []}
    cache = LYRIC_DIR / (re.sub(r"[^A-Za-z0-9_-]", "_", str(track_id)) + ".json")
    if cache.exists() and cache.stat().st_mtime > time.time() - 86400 * 14:
        try:
            return json.loads(cache.read_text())
        except Exception:
            pass
    if not ONLINE_LYRICS:
        return {"synced": False, "lines": []}
    url = "https://music.163.com/api/song/lyric?id=%s&lv=1&tv=1&kv=1" % track_id
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    try:
        with urllib.request.urlopen(req, timeout=6) as resp:
            data = json.loads(resp.read().decode("utf-8", "replace"))
    except Exception:
        return {"synced": False, "lines": []}
    lrc = ((data.get("lrc") or {}) or {}).get("lyric") or ""
    parsed = parse_lrc(lrc)
    out = {"synced": bool(parsed), "lines": parsed}
    try:
        cache.write_text(json.dumps(out, ensure_ascii=False))
    except Exception:
        pass
    return out


def art_uri(path):
    p = Path(path) if path else None
    if not p or not p.exists() or p.stat().st_size < 32:
        return None, None
    try:
        if p.stat().st_size > 180000:
            subprocess.run(
                ["sips", "-Z", "128", str(p)],
                capture_output=True,
                timeout=4,
            )
        raw = p.read_bytes()
        if len(raw) > 250000:
            return None, None
        b64 = base64.b64encode(raw).decode("ascii")
        return "data:image/jpeg;base64," + b64, b64
    except Exception:
        return None, None


def clip(s, n=120):
    s = (s or "").strip()
    return s if len(s) <= n else s[: n - 1] + "…"


def main():
    persisted = load_state()
    control_error = None

    if EVENT == "launch":
        subprocess.run(["open", "-b", BUNDLE], check=False)
        time.sleep(0.8)

    running = ncm_running()

    if EVENT == "trigger" and isinstance(PAYLOAD, dict):
        bid = PAYLOAD.get("bundleID") or PAYLOAD.get("bundleId") or ""
        if PAYLOAD.get("kind") == "workspace" and bid == BUNDLE and not running:
            running = False

    if running and EVENT in ("playpause", "next", "prev"):
        if EVENT == "playpause":
            st, err = click_playpause()
            if st != "ok":
                control_error = st
            time.sleep(0.25)
        elif EVENT == "next":
            st, err = click_named(MENU["next"])
            if st != "ok":
                control_error = st
            time.sleep(0.35)
        elif EVENT == "prev":
            st, err = click_named(MENU["prev"])
            if st != "ok":
                control_error = st
            time.sleep(0.35)

    running = ncm_running()
    if not running:
        widget = {
            "status": "not_running",
            "title": "",
            "artist": "",
            "album": "",
            "duration": 0,
            "position": 0,
            "volume": int(persisted.get("volume", 50)),
            "trackId": "",
            "art": None,
            "lyrics": {"synced": False, "lines": []},
            "showLyrics": ONLINE_LYRICS,
        }
        save_state({**persisted, "was_playing": False, "track_key": ""})
        notch_result(
            summary=notch_t("summary_not_running"),
            widget=widget,
            notification={"end": "now-playing"},
            icon="off",
        )
        return

    if control_error == "permission_required":
        widget = {
            "status": "permission_required",
            "title": "",
            "artist": "",
            "album": "",
            "duration": 0,
            "position": 0,
            "volume": int(persisted.get("volume", 50)),
            "trackId": "",
            "art": None,
            "lyrics": {"synced": False, "lines": []},
            "showLyrics": ONLINE_LYRICS,
        }
        notch_result(
            summary=notch_t("summary_permission"),
            widget=widget,
            notification={"end": "now-playing"},
            icon="off",
        )
        return

    menu_playing, perm, _ = playing_from_menu()
    if perm == "permission_required":
        widget = {
            "status": "permission_required",
            "title": "",
            "artist": "",
            "album": "",
            "duration": 0,
            "position": 0,
            "volume": int(persisted.get("volume", 50)),
            "trackId": "",
            "art": None,
            "lyrics": {"synced": False, "lines": []},
            "showLyrics": ONLINE_LYRICS,
        }
        notch_result(
            summary=notch_t("summary_permission"),
            widget=widget,
            notification={"end": "now-playing"},
            icon="off",
        )
        return

    mr = mr_info()
    ncm_np = is_ncm_now_playing(mr)
    title = (mr.get("title") or "") if ncm_np else ""
    artist = (mr.get("artist") or "") if ncm_np else ""
    album = (mr.get("album") or "") if ncm_np else ""
    duration = float(mr["duration"]) if ncm_np and isinstance(mr.get("duration"), (int, float)) else 0.0
    elapsed = float(mr["elapsed"]) if ncm_np and isinstance(mr.get("elapsed"), (int, float)) else 0.0
    rate = float(mr["rate"]) if ncm_np and isinstance(mr.get("rate"), (int, float)) else 0.0
    ts = float(mr["timestamp"]) if ncm_np and isinstance(mr.get("timestamp"), (int, float)) else 0.0
    mr_playing = bool(mr.get("playing")) if ncm_np else False

    playing = menu_playing if menu_playing is not None else mr_playing

    if ts and ncm_np:
        if playing and rate > 0:
            elapsed = max(0.0, elapsed + max(0.0, time.time() - ts) * rate)
        elif not playing:
            elapsed = max(0.0, elapsed)

    track = lookup_track(title, artist) if title else None
    if not title:
        track = fallback_track()
        if track:
            title = track.get("title") or ""
            artist = track.get("artist") or ""
            album = track.get("album") or album
            if duration <= 0 and track.get("duration_ms"):
                duration = float(track["duration_ms"]) / 1000.0

    track_id = (track or {}).get("id") or ""
    if duration <= 0 and track and track.get("duration_ms"):
        duration = float(track["duration_ms"]) / 1000.0

    if not title:
        status = "stopped"
        widget = {
            "status": status,
            "title": "",
            "artist": "",
            "album": "",
            "duration": 0,
            "position": 0,
            "volume": int(persisted.get("volume", 50)),
            "trackId": "",
            "art": None,
            "lyrics": {"synced": False, "lines": []},
            "showLyrics": ONLINE_LYRICS,
        }
        save_state({**persisted, "was_playing": False, "track_key": ""})
        notch_result(
            summary=notch_t("summary_idle"),
            widget=widget,
            notification={"end": "now-playing"},
            icon="off",
        )
        return

    status = "playing" if playing else "paused"
    lyrics = fetch_lyrics(track_id) if track_id else {"synced": False, "lines": []}
    art, art_b64 = art_uri(mr.get("artwork") if ncm_np else None)
    volume = int(persisted.get("volume", 50))

    widget = {
        "status": status,
        "title": clip(title, 80),
        "artist": clip(artist, 80),
        "album": clip(album, 80),
        "duration": round(duration, 3),
        "position": round(min(elapsed, duration) if duration else elapsed, 3),
        "volume": volume,
        "trackId": track_id,
        "art": art,
        "lyrics": lyrics,
        "showLyrics": ONLINE_LYRICS,
        "lyricsPending": bool(ONLINE_LYRICS and track_id and not lyrics.get("lines")),
    }

    track_key = "%s|%s|%s" % (track_id, title, artist)
    was_playing = bool(persisted.get("was_playing"))
    play_gen = int(persisted.get("play_gen", 0))
    if status == "playing" and (not was_playing or persisted.get("track_key") != track_key):
        play_gen += 1
    activation_id = "%s:play-%s" % (track_key[:80], play_gen)

    persisted.update({
        "was_playing": status == "playing",
        "track_key": track_key,
        "play_gen": play_gen,
        "activation_id": activation_id,
        "volume": volume,
    })
    save_state(persisted)

    lines = []
    for ln in (lyrics.get("lines") or [])[:300]:
        lines.append({"at_seconds": float(ln.get("t") or 0), "text": clip(ln.get("text") or "", 120)})

    notif = {
        "id": "now-playing",
        "type": "ongoing",
        "activation_id": activation_id,
        "title": clip(title, 120),
        "details": clip(artist, 120),
        "lines": lines,
        "position_seconds": widget["position"],
        "paused": status != "playing",
        "waveform": True,
        "spin_period_seconds": 8,
        "accent_hex": "#EC4141",
        "on_click": {"activate": BUNDLE},
        "actions": [
            {"id": "prev", "symbol": "backward.fill", "label": notch_t("notif_prev"), "invoke": "prev"},
            {
                "id": "playpause",
                "symbol": "pause.fill" if status == "playing" else "play.fill",
                "label": notch_t("notif_pause") if status == "playing" else notch_t("notif_play"),
                "invoke": "playpause",
            },
            {"id": "next", "symbol": "forward.fill", "label": notch_t("notif_next"), "invoke": "next"},
        ],
    }
    if widget["duration"]:
        notif["duration_seconds"] = widget["duration"]
    if art_b64:
        notif["icon"] = {"image_base64": art_b64}
    else:
        lb = logo_b64()
        notif["icon"] = {"image_base64": lb} if lb else {"symbol": "music.note"}

    notch_result(
        summary=clip(title, 80),
        details=clip(artist, 80),
        widget=widget,
        notification=notif,
        icon="playing" if status == "playing" else "paused",
    )


main()

widget.css:
html, body {
  margin: 0;
  height: 100%;
  background: transparent;
  overflow: hidden;
  -webkit-user-select: none;
  user-select: none;
}

.card {
  position: relative;
  box-sizing: border-box;
  height: 100%;
  padding: 9px 10px 8px;
  border-radius: 13px;
  background: rgba(255, 255, 255, .09);
